import { useState } from "react";

export function DetailsElement({
  summaryText = "{{summaryText}}",
  body = "{{body}}",
  accent = "{{accent}}",
  open: initialOpen = {{open}},
}) {
  const [open, setOpen] = useState(initialOpen);
  return (
    <div>
      <details open={open} onToggle={(e) => setOpen(e.target.open)}
        style={{ width: 340, boxSizing: "border-box", font: "15px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", border: "1.5px solid #24143025", borderRadius: 10, padding: "4px 18px" }}>
        <summary style={{ cursor: "pointer", padding: "14px 0", fontWeight: 700, display: "flex", justifyContent: "space-between", alignItems: "center", listStyle: "none" }}>
          {summaryText}
          <span aria-hidden="true" style={{ width: 9, height: 9, borderRight: `2px solid ${accent}`, borderBottom: `2px solid ${accent}`, transform: open ? "rotate(45deg)" : "rotate(-45deg)" }} />
        </summary>
        <p style={{ margin: "0 0 16px", fontSize: 14, color: "#241430cc" }}>{body}</p>
      </details>
      <p style={{ width: 340, marginTop: 10, fontSize: 12, color: "#24143088" }}>
        No JavaScript needed — click the summary to toggle. <code>open</code> is the real attribute.
      </p>
    </div>
  );
}
